module eb1_5 #(
	parameter WIDTH = 8,
	parameter S0 = 3'o0,
	parameter S1 = 3'o1,
	parameter S2 = 3'o2,
	parameter S3 = 3'o3,
	parameter S4 = 3'o4
) (
	input  clk, reset_n,
	input         [WIDTH-1:0] t0_data,
	input                     t0_valid,
	output logic              t0_ready,
	output logic  [WIDTH-1:0] i0_data,
	output logic              i0_valid,
	input                     i0_ready
);
logic [WIDTH-1:0] dat0, dat1;
logic [2:0] state, next_state;

always_ff @(posedge clk or negedge reset_n) begin
	if (!reset_n) begin
		state <= S0;
	end else begin
		state <= next_state;
	end
end

always_comb begin
	next_state = state;
	case (state)
		S0: begin
			if (t0_valid && i0_ready) begin
				next_state = S1;
			end
		end
		S1: begin
			if (t0_valid && i0_ready) begin
				next_state = S2;
			end
		end
		S2: begin
			if (t0_valid && i0_ready) begin
				next_state = S3;
			end
		end
		S3: begin
			if (t0_valid && i0_ready) begin
				next_state = S4;
			end
		end
		S4: begin
			if (t0_valid && i0_ready) begin
				next_state = S1;
			end
		end
		default: begin
			next_state = S0;
		end
	endcase
end

always_ff @(posedge clk or negedge reset_n) begin
	if (!reset_n) begin
		dat0 <= 0;
		dat1 <= 0;
	end else begin
		case (state)
			S0: begin
				dat0 <= 0;
				dat1 <= 0;
			end
			S1: begin
				dat0 <= t0_data;
				dat1 <= 0;
			end
			S2: begin
				dat0 <= 0;
				dat1 <= t0_data;
			end
			S3: begin
				dat0 <= 0;
				dat1 <= 0;
			end
			S4: begin
				dat0 <= 0;
				dat1 <= 0;
			end
			default: begin
				dat0 <= 0;
				dat1 <= 0;
			end
		endcase
	end
end

