module fifo_simple
#(
    parameter               WIDTH=16,
    parameter               DEPTH=16,
    parameter               PROG_FULL=14
)    
(
    input   wire                    reset_p,    
    input   wire                    clk,        

    input   wire    [WIDTH-1:0]     data_i,
    input   wire                    data_we,

    output  wire    [WIDTH-1:0]     data_o,
    input   wire                    data_rd,

    output  wire                    prog_full,
    output  wire                    full,
    output  wire                    empty,
    output  reg                     overflow,
    output  reg                     underflow

);
reg    [WIDTH-1:0]     mem [DEPTH-1:0];
    reg    [DEPTH-1:0]     wr_ptr;
    reg    [DEPTH-1:0]     rd_ptr;
    reg    [DEPTH-1:0]     word_cnt;

    assign data_o = mem[rd_ptr];

    assign prog_full = (word_cnt == PROG_FULL);
    assign full = (word_cnt == DEPTH);
    assign empty = (word_cnt == 0);

    always @(posedge clk or posedge reset_p) begin
        if (reset_p) begin
            wr_ptr <= 0;
            rd_ptr <= 0;
            word_cnt <= 0;
            overflow <= 0;
            underflow <= 0;
        end
        else begin
            if (data_we) begin
                if (word_cnt == DEPTH) begin
                    overflow <= 1;
                    wr_ptr <= wr_ptr;
                    rd_ptr <= rd_ptr;
                    word_cnt <= word_cnt;
                end
                else begin
                    overflow <= 0;
                    wr_ptr <= wr_ptr + 1;
                    rd_ptr <= rd_ptr;
                    word_cnt <= word_cnt + 1;
                end
            end
            else begin
                if (word_cnt == 0) begin
                    underflow <= 1;
                    wr_ptr <= wr_ptr;
                    rd_ptr <= rd_ptr;
                    word_cnt <= word_cnt;
                end
                else begin
                    underflow <= 0;
                    wr_ptr <= wr_ptr;
                    rd_ptr <= rd_ptr + 1;
                    word_cnt <= word_cnt - 1;
                end
            end
        end
    end

    always @(posedge clk or posedge reset_p) begin
        if (reset_p) begin
            mem <= 0;
        end
        else begin
            if (data_we) begin
                mem[wr_ptr] <= data_i;
            end
        end
    end

endmodule

module submulor_2_stage_unsigned_10_bit(
	input  [9:0] a,
	input  [9:0] b,
	input  [9:0] c,
	input  [9:0] d,
	output [9:0] out,
	input clk);
logic  [19:0] stage0;
	logic  [19:0] stage1;

	always @(posedge clk) begin
	stage0 <= ((d - a) * b) | c;
	stage1 <= stage0;
	end

	assign out = stage1;
endmodule

