endmodule

module vga_ctrl(
input wire pixel_clk,
output wire hsync,
output wire vsync,
output wire [9:0] pixel_x,
output wire [9:0] pixel_y,
output wire visible_region
); 

parameter [31:0] H_TOTAL=800;
parameter [31:0] H_SYNC=96;
parameter [31:0] H_BACK=48;
parameter [31:0] H_FRONT=48;
parameter [31:0] V_TOTAL=525;
parameter [31:0] V_SYNC=2;
parameter [31:0] V_BACK=33;
parameter [31:0] V_FRONT=10;
reg [9:0] h_counter = 0;
reg [9:0] v_counter = 0;
reg [9:0] pixel_x_reg = 0;
reg [9:0] pixel_y_reg = 0;
reg visible_region_reg = 0;
  always @(posedge pixel_clk) begin
    if((h_counter == (H_TOTAL - 1))) begin
      h_counter <= 0;
      if((v_counter == (V_TOTAL - 1))) begin
        v_counter <= 0;
      end
      else begin
        v_counter <= v_counter + 1;
      end
    end
    else begin
      h_counter <= h_counter + 1;
    end
    if((h_counter < (H_SYNC + H_BACK))) begin
      hsync <= 1;
    end
    else if((h_counter < (H_SYNC + H_BACK + H_FRONT))) begin
      hsync <= 0;
    end
    else begin
      hsync <= 1;
    end
    if((v_counter < (V_SYNC + V_BACK))) begin
      vsync <= 1;
    end
    else if((v_counter < (V_SYNC + V_BACK + V_FRONT))) begin
      vsync <= 0;
    end
    else begin
      vsync <= 1;
    end
    if((h_counter < (H_SYNC + H_BACK + H_FRONT)) && (v_counter < (V_SYNC + V_BACK + V_FRONT))) begin
      visible_region_reg <= 1;
    end
    else begin
      visible_region_reg <= 0;
    end
    pixel_x_reg <= h_counter;
    pixel_y_reg <= v_counter;
  end
  assign pixel_x = pixel_x_reg;
  assign pixel_y = pixel_y_reg;
  assign visible_region = visible_region_reg;
endmodule

