reg ifetch;
reg ifetch_cancel;
reg [7:0] cpu_opcode;
wire [7:0] opcode;
  assign opcode = cpu_opcode;
  assign ifetch = (i_m1_n == 1'b0) && (i_mreq_n == 1'b0) && (i_iorq_n == 1'b0);
