module clk_div(
input wire clk_i,
output reg clk_o,
output wire [1:0] count_o
); 

reg [1:0] count = 0;
  always @(posedge clk_i) begin
    if(count == 2'b11) begin
      count <= 2'b00;
    end
    else begin
      count <= count + 1;
    end
    if(count == 2'b01) begin
      clk_o <= 1'b1;
    end
    else begin
      clk_o <= 1'b0;
    end
  end
  assign count_o = count;
endmodule

