module toe_s_axis_listen_port_req_reg_slice
#(parameter
    N = 8   
) (

    input  wire         clk,
    input  wire         reset,

    input  wire [N-1:0] s_data,
    input  wire         s_valid,
    output wire         s_ready,

    output wire [N-1:0] m_data,
    output wire         m_valid,
    input  wire         m_ready
);
localparam [1:0]
    ZERO = 2'b00,
    ONE  = 2'b01,
    TWO  = 2'b10;

reg  [N-1:0] data_p1;
reg  [N-1:0] data_p2;
reg          state;
reg          s_ready_reg;

assign s_ready = s_ready_reg;
assign m_data  = data_p2;
assign m_valid = (state == TWO) ? m_ready : 1'b0;

always @(posedge clk) begin
    if (reset) begin
        state <= ZERO;
        s_ready_reg <= 1'b0;
    end
    else begin
        case (state)
            ZERO : begin
                if (s_valid) begin
                    state <= ONE;
                    s_ready_reg <= 1'b1;
                    data_p1 <= s_data;
                end
                else begin
                    s_ready_reg <= 1'b0;
                end
            end
            ONE : begin
                if (s_valid & s_ready) begin
                    state <= TWO;
                    s_ready_reg <= 1'b0;
                    data_p2 <= s_data;
                end
                else if (~s_valid & s_ready) begin
                    state <= ZERO;
                    s_ready_reg <= 1'b0;
                end
                else begin
                    s_ready_reg <= 1'b1;
                end
            end
            TWO : begin
                if (m_ready) begin
                    state <= ONE;
                    s_ready_reg <= 1'b1;
                end
                else begin
                    s_ready_reg <= 1'b0;
                end
            end
            default : begin
                state <= ZERO;
                s_ready_reg <= 1'b0;
            end
        endcase
    end
end

endmodule

