module AXI_WRITE_DATA_CHANNEL_model(
input wire clk,
input wire resetn,
input wire [31:0] data,
input wire go,
output reg done,
output wire [31:0] WDATA,
output reg [3:0] WSTRB,
output reg WVALID,
input wire WREADY
); 

parameter [1:0]
  reset = 0,
  idle = 1,
  running = 2,
  complete = 3;
reg [1:0] current_state;
reg [1:0] next_state;
  always @(posedge clk) begin
    if((resetn == 1'b0)) begin
      current_state <= reset;
    end
    else begin
      current_state <= next_state;
    end
  end
  always @(current_state, go, WREADY) begin
    next_state <= current_state;
    done <= 1'b0;
    WDATA <= 32'h00000000;
    WSTRB <= 4'h0;
    WVALID <= 1'b0;
    case(current_state)
    reset : begin
      if((go == 1'b1)) begin
        next_state <= idle;
      end
    end
    idle : begin
      if((go == 1'b1)) begin
        next_state <= running;
        WDATA <= data;
        WSTRB <= 4'hf;
        WVALID <= 1'b1;
      end
    end
    running : begin
      if((WREADY == 1'b1)) begin
        next_state <= complete;
        done <= 1'b1;
      end
    end
    complete : begin
      next_state <= idle;
    end
    default : begin
      next_state <= reset;
    end
    endcase
  end
endmodule

