module jtframe_romrq #(parameter AW=18, DW=8 )(
    input               rst,
    input               clk,
    input               clr, 
    input [21:0]        offset,
    input [AW-1:0]      addr,
    input               addr_ok,    
    input [31:0]        din,
    input               din_ok,
    input               we,
    output reg          req,
    output reg          data_ok,    
    output     [21:0]   sdram_addr,
    output reg [DW-1:0] dout
);
reg [AW-1:0] addr_req;
    reg [AW-1:0] cached_addr0;
    reg [AW-1:0] cached_addr1;
    reg [DW-1:0] cached_data0;
    reg [DW-1:0] cached_data1;
    reg [21:0] subaddr;
    reg good;
    always @(*) begin
        if (addr_ok) begin
            if (DW == 8) begin
                addr_req = {addr[AW-1:2], 2'b00};
            end else if (DW == 16) begin
                addr_req = {addr[AW-1:3], 1'b0};
            end else if (DW == 32) begin
                addr_req = {addr[AW-1:4], 0};
            end
        end else begin
            addr_req = 0;
        end
    end
    always @(*) begin
        if (addr_req == cached_addr0) begin
            hit0 = 1;
        end else begin
            hit0 = 0;
        end
        if (addr_req == cached_addr1) begin
            hit1 = 1;
        end else begin
            hit1 = 0;
        end
    end
    always @(*) begin
        if (addr_req == 0) begin
            req = 0;
        end else if (hit0 == 0 && hit1 == 0) begin
            req = 1;
        end else if (hit0 == 1 && hit1 == 0) begin
            req = 1;
        end else if (hit0 == 0 && hit1 == 1) begin
            req = 1;
        end else begin
            req = 0;
        end
    end
    always @(*) begin
        if (addr_req == 0) begin
            sdram_addr = 0;
        end else if (DW == 8) begin
            sdram_addr = {addr_req[AW-1:2], offset};
        end else if (DW == 16) begin
            sdram_addr = {addr_req[AW-1:3], offset};
        end else if (DW == 32) begin
            sdram_addr = {addr_req[AW-1:4], offset};
        end
    end
    always @(*) begin
        if (addr_req == 0) begin
            subaddr = 0;
        end else if (DW == 8) begin
            subaddr = addr_req[1:0];
        end else if (DW == 16) begin
            subaddr = addr_req[2:0];
        end else if (DW == 32) begin
            subaddr = addr_req[3:0];
        end
    end
    always @(*) begin
        if (addr_req == 0) begin
            dout = 0;
        end else if (subaddr == 0) begin
            dout = cached_data0;
        end else if (subaddr == 1) begin
            dout = cached_data1;
        end
    end
    always @(posedge clk or posedge rst) begin
        if (rst) begin
            good <= 0;
        end else begin
            if (we) begin
                if (subaddr == 0) begin
                    cached_data0 <= din;
                end else if (subaddr == 1) begin
                    cached_data1 <= din;
                end
                good <= 1;
            end else begin
                good <= 0;
            end
        end
    end
    always @(posedge clk or posedge rst) begin
        if (rst) begin
            cached_addr0 <= 0;
            cached_addr1 <= 0;
        end else begin
            if (hit0) begin
                cached_addr0 <= addr_req;
            end
            if (hit1) begin
                cached_addr1 <= addr_req;
            end
        end
    end
    always @(posedge clk or posedge rst) begin
        if (rst) begin
            cached_data0 <= 0;
            cached_data1 <= 0;
        end else begin
            if (we) begin
                if (subaddr == 0) begin
                    cached_data0 <= din;
                end else if (subaddr == 1) begin
                    cached_data1 <= din;
                end
            end
        end
    end
    always @(posedge clk or posedge rst) begin
        if (rst) begin
            data_ok <= 0;
        end else begin
            if (we) begin
                data_ok <= 1;
            end else begin
                data_ok <= good;
            end
        end
    end
endmodule

