module Data_Memory(
	input reset,
	input [31:0] address,
	input [31:0] write_data,
	input memRead,
	input memWrite,
	input [2:0] func3,
	output reg [31:0] read_data
    );
reg [7:0] mem [0:2**20-1];
integer i;
initial begin
	$readmemb("data_memory.txt", mem);
end
always @(posedge reset) begin
	if (reset) begin
		read_data <= 0;
	end
	else begin
		if (memRead) begin
			if (func3 == 3'b000) begin
				read_data <= mem[address];
			end
			else if (func3 == 3'b001) begin
				read_data <= {mem[address+1], mem[address]};
			end
			else if (func3 == 3'b010) begin
				read_data <= {mem[address+2], mem[address+1], mem[address]};
			end
			else if (func3 == 3'b011) begin
				read_data <= {mem[address+3], mem[address+2], mem[address+1], mem[address]};
			end
			else if (func3 == 3'b100) begin
				read_data <= {mem[address+1], mem[address]};
			end
			else if (func3 == 3'b101) begin
				read_data <= {mem[address+2], mem[address+1], mem[address]};
			end
			else if (func3 == 3'b110) begin
				read_data <= {mem[address+3], mem[address+2], mem[address+1], mem[address]};
			end
			else if (func3 == 3'b111) begin
				read_data <= {mem[address+3], mem[address+2], mem[address+1], mem[address]};
			end
		end
		if (memWrite) begin
			if (func3 == 3'b000) begin
				mem[address] <= write_data[7:0];
			end
			else if (func3 == 3'b001) begin
				mem[address] <= write_data[7:0];
				mem[address+1] <= write_data[15:8];
			end
			else if (func3 == 3'b010) begin
				mem[address] <= write_data[7:0];
				mem[address+1] <= write_data[15:8];
				mem[address+2] <= write_data[23:16];
				mem[address+3] <= write_data[31:24];
			end
			else if (func3 == 3'b011) begin
				mem[address] <= write_data[7:0];
				mem[address+1] <= write_data[15:8];
				mem[address+2] <= write_data[23:16];
				mem[address+3] <= write_data[31:24];
			end
			else if (func3 == 3'b100) begin
				mem[address] <= write_data[7:0];
			end
			else if (func3 == 3'b101) begin
				mem[address] <= write_data[7:0];
				mem[address+1] <= write_data[15:8];
			end
			else if (func3 == 3'b110) begin
				mem[address] <= write_data[7:0];
				mem[address+1] <= write_data[15:8];
				mem[address+2] <= write_data[23:16];
				mem[address+3] <= write_data[31:24];
			end
			else if (func3 == 3'b111) begin
				mem[address] <= write_data[7:0];
				mem[address+1] <= write_data[15:8];
				mem[address+2] <= write_data[23:16];
				mem[address+3] <= write_data[31:24];
