module UARTTransmitter(
  input        clock,
               reset,
               io_valid,
  input  [7:0] io_bits,
  input        tick,
  output       io_ready,
               tx
);
reg [3:0] state;
  reg [7:0] data;
  reg       ready;
  always @(posedge clock) begin
    if (reset) begin
      state <= 4'd0;
      data  <= 8'd0;
      ready <= 1'b0;
    end
    else begin
      case (state)
        4'd0: begin
          if (io_valid) begin
            state <= 4'd1;
            data  <= io_bits;
          end
          else begin
            state <= 4'd0;
            data  <= 8'd0;
          end
        end
        4'd1: begin
          if (tick) begin
            state <= 4'd2;
            data  <= {data[6:0], 1'b0};
          end
        end
        4'd2: begin
          if (tick) begin
            state <= 4'd3;
            data  <= {data[6:0], 1'b0};
          end
        end
        4'd3: begin
          if (tick) begin
            state <= 4'd4;
            data  <= {data[6:0], 1'b0};
          end
        end
        4'd4: begin
          if (tick) begin
            state <= 4'd5;
            data  <= {data[6:0], 1'b0};
          end
        end
        4'd5: begin
          if (tick) begin
            state <= 4'd6;
            data  <= {data[6:0], 1'b0};
          end
        end
        4'd6: begin
          if (tick) begin
            state <= 4'd7;
            data  <= {data[6:0], 1'b0};
          end
        end
        4'd7: begin
          if (tick) begin
            state <= 4'd0;
            data  <= 8'd0;
            ready <= 1'b1;
          end
        end
        default: begin
          state <= 4'd0;
          data  <= 8'd0;
          ready <= 1'b0;
        end
      endcase
    end
  end
  assign io_ready = ready;
  assign tx = data[7];
endmodule

