reg         load_p1_from_p2;
reg         s_ready_int;
reg         m_valid_int;
reg  [1:0]  state;
reg  [1:0]  next_state;

always @(posedge clk) begin
    if (reset) begin
        state <= ZERO;
    end else begin
        state <= next_state;
    end
end

always @(state, s_valid, m_ready) begin
    case (state)
        ZERO: begin
            if (s_valid && m_ready) begin
                next_state <= ONE;
            end else begin
                next_state <= ZERO;
            end
        end
        ONE: begin
            if (s_valid && m_ready) begin
                next_state <= TWO;
            end else begin
                next_state <= ONE;
            end
        end
        TWO: begin
            if (s_valid && m_ready) begin
                next_state <= TWO;
            end else begin
                next_state <= ZERO;
            end
        end
        default: begin
            next_state <= ZERO;
        end
    endcase
end

always @(posedge clk) begin
    if (reset) begin
        s_ready_int <= 1'b0;
    end else begin
        case (state)
            ZERO: begin
