module QueueCompatibility_14( 
  input        clock, 
  input        reset, 
  output       io_enq_ready, 
  input        io_enq_valid, 
  input  [3:0] io_enq_bits_tl_state_size, 
  input  [1:0] io_enq_bits_tl_state_source, 
  input        io_deq_ready, 
  output       io_deq_valid, 
  output [3:0] io_deq_bits_tl_state_size, 
  output [1:0] io_deq_bits_tl_state_source 
);
wire  do_enq; 
  wire  do_deq; 
  wire  maybe_full; 
  wire  maybe_empty; 
  wire  io_deq_bits_tl_state_size; 
  wire  io_deq_bits_tl_state_source; 
  assign do_enq = io_enq_ready & io_enq_valid; 
  assign do_deq = io_deq_ready & io_deq_valid; 
  assign maybe_full = do_enq - do_deq; 
  assign io_enq_ready = ~maybe_full; 
  assign io_deq_valid = ~maybe_empty; 
  assign io_deq_bits_tl_state_size = io_enq_bits_tl_state_size; 
  assign io_deq_bits_tl_state_source = io_enq_bits_tl_state_source; 
  always @(posedge clock) begin
    if (reset) begin
      maybe_empty <= 1'h0;
    end else begin
      if (do_deq) begin
        maybe_empty <= 1'h0;
      end
      if (do_enq) begin
        maybe_empty <= 1'h1;
      end
    end
  end
endmodule

