module multpool_rdata_mux #(
  parameter NBITS     = 256,
  parameter NUM_RDATA = 1024) (
  input  wire               hclk,     
  input  wire               hresetn,  
  input  wire [3*NBITS-1:0] rdata [0 :NUM_RDATA-1],
  input  wire               valid_rd,
  output wire [3*NBITS-1:0] hrdata
);
reg [3*NBITS-1:0] rdata0 [0 :NUM_RDATA/4-1];
reg [3*NBITS-1:0] rdata1 [0 :NUM_RDATA/4-1];
reg [3*NBITS-1:0] rdata2 [0 :NUM_RDATA/4-1];
reg [3*NBITS-1:0] rdata3 [0 :NUM_RDATA/4-1];
reg [3*NBITS-1:0] rdata0_out;
reg [3*NBITS-1:0] rdata1_out;
reg [3*NBITS-1:0] rdata2_out;
reg [3*NBITS-1:0] rdata3_out;
always @ (posedge hclk or negedge hresetn) begin
  if (!hresetn) begin
    rdata0_out <= 0;
    rdata1_out <= 0;
    rdata2_out <= 0;
    rdata3_out <= 0;
  end else begin
    if (valid_rd) begin
      rdata0_out <= rdata0[0];
      rdata1_out <= rdata1[0];
      rdata2_out <= rdata2[0];
      rdata3_out <= rdata3[0];
      for (int i = 1; i < NUM_RDATA/4; i = i + 1) begin
        rdata0_out = rdata0_out | rdata0[i];
        rdata1_out = rdata1_out | rdata1[i];
        rdata2_out = rdata2_out | rdata2[i];
        rdata3_out = rdata3_out | rdata3[i];
      end
    end
  end
end
always @ (posedge hclk or negedge hresetn) begin
  if (!hresetn) begin
    rdata0 <= 0;
    rdata1 <= 0;
    rdata2 <= 0;
    rdata3 <= 0;
  end else begin
    if (valid_rd) begin
      rdata0 <= rdata[0 : NUM_RDATA/4-1];
      rdata1 <= rdata[NUM_RDATA/4 : 2*NUM_RDATA/4-1];
      rdata2 <= rdata[2*NUM_RDATA/4 : 3*NUM_RDATA/4-1];
      rdata3 <= rdata[3*NUM_RDATA/4 : NUM_RDATA-1];
    end
  end
end
assign hrdata = rdata0_out | rdata1_out | rdata2_out | rdata3_out;
endmodule

