module serial2parallel(
    input clk,
    input rst_n,
    input din_serial,
    input din_valid,
    output reg [7:0] dout_parallel,
    output reg dout_valid
);
reg [3:0] counter;
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            counter <= 4'd0;
            dout_parallel <= 8'd0;
            dout_valid <= 1'b0;
        end
        else begin
            if (din_valid) begin
                dout_parallel <= {dout_parallel[6:0], din_serial};
                counter <= counter + 4'd1;
                if (counter == 4'd7) begin
                    dout_valid <= 1'b1;
                    counter <= 4'd0;
                end
                else begin
                    dout_valid <= 1'b0;
                end
            end
        end
    end
endmodule

