module Control(
   
	input wire clk,rst,
	input [7:0] in3,in2,in1,in0,
	output reg [3:0] anodo,
	output reg [7:0] catodo
    );
local parameter N = 18;
reg [N-1:0] q_reg;
always @(posedge clk or posedge rst)
begin
	if(rst)
		q_reg <= 0;
	else
		q_reg <= q_reg + 1;
end
always @(q_reg)
begin
	case(q_reg[17:16])
		2'b00: anodo <= 4'b0001;
		2'b01: anodo <= 4'b0010;
		2'b10: anodo <= 4'b0100;
		2'b11: anodo <= 4'b1000;
	endcase
	case(q_reg[15:14])
		2'b00: catodo <= in0;
		2'b01: catodo <= in1;
		2'b10: catodo <= in2;
		2'b11: catodo <= in3;
