module mylfsr2(
input wire [7:0] starting,
output wire [7:0] lfsr2_out,
input wire clk,
input wire rst,
input wire en
);
reg [7:0] lfsr2;
  always @(posedge clk, posedge rst) begin
    if((rst == 1'b0)) begin
      lfsr2 <= starting;
    end else begin
      if((en == 1'b1)) begin
        lfsr2[0] <= lfsr2[7] ^ lfsr2[6] ^ lfsr2[5] ^ lfsr2[4] ^ lfsr2[3] ^ lfsr2[2] ^ lfsr2[1];
        lfsr2[7:1] <= lfsr2[6:0];
      end
    end
  end
  assign lfsr2_out = lfsr2;
endmodule

