module scan_hex_led_disp(
    input clk,reset,
    input [3:0] hex3,hex2,hex1,hex0,
    input [3:0] dp,
    output reg[3:0] en, 
    output reg[7:0] sseg
    );
reg [3:0] cnt;
    always@(posedge clk or posedge reset)
    begin
        if(reset)
            cnt<=0;
        else
            cnt<=cnt+1;
    end
    always@(posedge clk or posedge reset)
    begin
        if(reset)
        begin
            en<=4'b0000;
            sseg<=8'b11111111;
        end
        else
        begin
            case(cnt)
                0:begin
                    en<=4'b0001;
                    sseg<=hex0;
                end
                1:begin
                    en<=4'b0010;
                    sseg<=hex1;
                end
                2:begin
                    en<=4'b0100;
                    sseg<=hex2;
                end
                3:begin
                    en<=4'b1000;
                    sseg<=hex3;
                end
                default:begin
                    en<=4'b0000;
                    sseg<=8'b11111111;
                end
            endcase
        end
    end
endmodule

module Barrel15L_16(
    input [13:0] data_i,
    input [1:0] shift_i,
    output reg [16:0] data_o
    );
wire [16:0] tmp;
    always @(*) begin
        tmp = {{3{data_i[13]}}, data_i};
        case (shift_i)
            2'b00: data_o = tmp;
            2'b01: data_o = tmp << 1;
            2'b10: data_o = tmp << 2;
            2'b11: data_o = tmp << 3;
        endcase
    end
endmodule

module decoder_3to8 
    (input [2:0] a,
     input enable,
     output reg [7:0] y
    );
always @ (a or enable)
    begin
        if (enable == 0)
            y = 8'b00000000;
        else
            case (a)
                3'b000: y = 8'b00000001;
                3'b001: y = 8'b00000010;
                3'b010: y = 8'b00000100;
                3'b011: y = 8'b00001000;
                3'b100: y = 8'b00010000;
                3'b101: y = 8'b00100000;
                3'b110: y = 8'b01000000;
                3'b111: y = 8'b10000000;
                default: y = 8'b00000000;
            endcase
    end
endmodule

module Data_Memory(input clk, rst, MemWrite, MemRead, mem_to_reg,
input [31:0] addr, write_data, output [31:0] read_data);
reg [31:0] data [31:0];
    initial begin
        $display("Data Memory Initialized");
        for (int i = 0; i < 32; i = i + 1) begin
            data[i] = 0;
        end
    end
    always @(posedge clk) begin
        if (MemWrite) begin
            data[addr] = write_data;
        end
    end
    assign read_data = MemRead ? data[addr] : 0;
endmodule

module binary_updown_counter #(parameter BITS = 1)
        (input wire clk, input wire rst, input wire ena,
         input wire updown, output wire [BITS - 1:0] out, output wire ovf);
reg [BITS - 1:0] cnt;
    wire [BITS - 1:0] enable_wires;
    generate
        genvar i;
        for (i = 0; i < BITS; i = i + 1) begin
            assign enable_wires[i] = ena;
            always @(posedge clk or posedge rst) begin
                if (rst) begin
                    cnt[i] <= 0;
                end else if (enable_wires[i]) begin
                    if (updown) begin
                        cnt[i] <= cnt[i] + 1;
                    end else begin
                        cnt[i] <= cnt[i] - 1;
                    end
                end
            end
        end
    endgenerate
    assign out = cnt;
    assign ovf = (cnt[BITS - 1] & ~cnt[BITS - 2]) | (~cnt[BITS - 1] & cnt[BITS - 2]);
endmodule

module BCD(
		input [15:0] binary,
		output wire [3:0] b,
		output wire [3:0] s,
		output wire [3:0] g,
		output wire [3:0] q
		);
reg [31:0] r;
		integer i;
		always @(*) begin
			r = binary;
			for (i = 0; i < 16; i = i + 1) begin
				if (r[15:12] > 4) begin
					r[15:12] = r[15:12] + 3;
				end
				if (r[11:8] > 4) begin
					r[11:8] = r[11:8] + 3;
				end
				if (r[7:4] > 4) begin
					r[7:4] = r[7:4] + 3;
				end
				if (r[3:0] > 4) begin
					r[3:0] = r[3:0] + 3;
				end
				r = r >> 4;
			end
			b = r[3:0];
			s = r[7:4];
			g = r[11:8];
			q = r[15:12];
		end
endmodule

module Data_Memory 
#(	
	parameter DATA_WIDTH = 32,
	parameter MEMORY_DEPTH = 64
)
(
	input clk, Write_Enable_i, 
	input [DATA_WIDTH-1:0] Write_Data_i,
	input [DATA_WIDTH-1:0]  Address_i,
	output [(DATA_WIDTH-1):0]  Read_Data_o
);
reg [DATA_WIDTH-1:0] memory [MEMORY_DEPTH-1:0];
	reg [DATA_WIDTH-1:0] Var_i = 32'h10010000;

	always @(posedge clk) begin
		if (Write_Enable_i) begin
			memory[Address_i - Var_i >> 2] <= Write_Data_i;
		end
	end

	assign Read_Data_o = memory[Address_i - Var_i >> 2];
endmodule

