    input I_CLK,
    output reg O_CLK
);
reg [31:0] counter;
    initial
    begin
        O_CLK = 0;
    end
    always @(posedge I_CLK)
    begin
        if (counter < (Time/2))
        begin
            counter = counter + 1;
            O_CLK = 1;
        end
        else
        begin
            counter = 0;
            O_CLK = 0;
        end
    end
endmodule

