            end
            3'b100: begin
                y = a ^ b;
                cf = 0;
            end
            default: begin
                y = 0;
                cf = 0;
            end
        endcase
        zf = (y == 0);
        of = (a[WIDTH - 1] ^ b[WIDTH - 1] ^ y[WIDTH - 1]) & (cf | y[WIDTH - 1]);
    end
endmodule

