        full  <= 0;
        index <= 0;
    end
    else begin
        if (write && ~full) begin
            mem[index] <= din;
            index <= index + 1;
            if (index == DEPTH-1) begin
                empty <= 1;
                full  <= 0;
            end
        end
        else if (read && ~empty) begin
            index <= index - 1;
            if (index == 0) begin
                empty <= 0;
                full  <= 1;
            end
        end
    end
end

endmodule

module debounce(
input clk,
input btn_input,
output reg btn_output
);
reg [31:0] timer;
reg pre;
always@(posedge clk)
begin
if(timer<1000000)
begin
timer=timer+1;
end
else
begin
if(btn_input==pre)
begin
btn_output=btn_input;
pre=btn_input;
timer=0;
end
end
end
endmodule

