module dpram_async
#(
    parameter ADDR_WIDTH = 32,
    parameter DATA_WIDTH = 32,
    parameter CLEAR_ON_INIT = 1,
    parameter ENABLE_BYPASS = 1
)
(
    clk,
    rst,
    raddr,
    re,
    waddr,
    we,
    din,
    dout
);


input                           clk;
input                           rst;
input [ADDR_WIDTH-1:0]          raddr;
input                           re;
input [ADDR_WIDTH-1:0]          waddr;
input                           we;
input [DATA_WIDTH-1:0]          din;
output [DATA_WIDTH-1:0]         dout;
reg [DATA_WIDTH-1:0]           mem [2**ADDR_WIDTH-1:0];
reg [DATA_WIDTH-1:0]           dout_tmp;

initial
begin
    if (CLEAR_ON_INIT)
    begin
        for (int i = 0; i < 2**ADDR_WIDTH; i = i + 1)
        begin
            mem[i] = 0;
        end
    end
end

assign dout = (ENABLE_BYPASS && re && (raddr == waddr)) ? din : dout_tmp;

always @(posedge clk)
begin
    if (we)
    begin
        mem[waddr] <= din;
    end
end

always @(posedge clk)
begin
    if (re)
    begin
        dout_tmp <= mem[raddr];
    end
end

endmodule

