module Fibonacci_Series
( 
    input wire CLK_IN,
    input wire RST_N,
    output wire [7:0]SEQUENCE
);
reg [7:0] last_fib;
reg [7:0] second_last_fib;
wire [7:0] next_fib;

assign next_fib = last_fib + second_last_fib;
assign SEQUENCE = last_fib;

always @(posedge CLK_IN or negedge RST_N) begin
    if (!RST_N) begin
        last_fib <= 0;
        second_last_fib <= 0;
    end
    else begin
        last_fib <= next_fib;
        second_last_fib <= last_fib;
    end
end

endmodule

