module adapter_rgb_2_ppfifo #(
  parameter                 DATA_WIDTH = 24
)(
  input                             clk,
  input                             rst,

  input         [23:0]              i_rgb,
  input                             i_h_sync,
  input                             i_h_blank,
  input                             i_v_sync,
  input                             i_v_blank,
  input                             i_data_en,


  output                            o_ppfifo_clk,
  input       [1:0]                 i_ppfifo_rdy,
  output  reg [1:0]                 o_ppfifo_act,
  input       [23:0]                i_ppfifo_size,
  output  reg                       o_ppfifo_stb,
  output  reg [DATA_WIDTH - 1:0]    o_ppfifo_data


);
localparam  IDLE = 2'b00;
  localparam  READY = 2'b01;
  localparam  RELEASE = 2'b10;

  reg [1:0] state;
  reg [1:0] next_state;
  reg [1:0] r_count;

  always @(posedge clk) begin
    if (rst) begin
      state <= IDLE;
      r_count <= 0;
      o_ppfifo_act <= 0;
      o_ppfifo_stb <= 0;
      o_ppfifo_data <= 0;
    end
    else begin
      state <= next_state;
      r_count <= r_count + 1;
      o_ppfifo_act <= state[1];
      o_ppfifo_stb <= state[0];
      o_ppfifo_data <= i_rgb;
    end
  end

  always @(*) begin
    next_state = state;
    case (state)
      IDLE: begin
        if (i_ppfifo_rdy[0] == 1'b1) begin
          next_state = READY;
        end
      end
      READY: begin
        if (i_v_blank == 1'b0) begin
          if (r_count < i_ppfifo_size) begin
            next_state = READY;
          end
          else begin
            next_state = RELEASE;
          end
        end
      end
      RELEASE: begin
        next_state = IDLE;
      end
    endcase
  end

endmodule

