module matrix5arb (
   		   input clk,
   		   input rst_n,
   		   input [4:0] req,
   		   output [4:0] grant
   		   );
reg [4:0] state;
   always @(posedge clk or negedge rst_n) begin
      if (!rst_n) begin
	 state <= 5'b00000;
      end else begin
	 if (req[0] && !req[1] && !req[2] && !req[3] && !req[4]) begin
	    state <= 5'b00001;
	 end else if (req[1] && !req[2] && !req[3] && !req[4]) begin
	    state <= 5'b00010;
	 end else if (req[2] && !req[3] && !req[4]) begin
	    state <= 5'b00011;
	 end else if (req[3] && !req[4]) begin
	    state <= 5'b00100;
	 end else if (req[4]) begin
	    state <= 5'b00101;
	 end else begin
	    state <= 5'b00000;
	 end
      end
   end
   assign grant = state;
endmodule

module routing_buffer(clock, resetn, 
  i_datain, i_datain_valid, o_datain_stall, 
  o_dataout, i_dataout_stall, o_dataout_valid);

 input clock, resetn;
 input [DATA_WIDTH-1:0] i_datain;
 input i_datain_valid;
 output reg o_datain_stall;
 output reg [DATA_WIDTH-1:0] o_dataout;
 input i_dataout_stall;
 output reg o_dataout_valid;
parameter DATA_WIDTH = 32;
 parameter INSERT_REGISTER = 1;

 reg [DATA_WIDTH-1:0] r_dataout;
 reg r_dataout_valid;
 reg r_dataout_stall;

 always @ (posedge clock or negedge resetn) begin
  if (!resetn) begin
   r_dataout <= 0;
   r_dataout_valid <= 0;
   r_dataout_stall <= 0;
  end
  else begin
   if (o_datain_stall) begin
    r_dataout <= 0;
    r_dataout_valid <= 0;
    r_dataout_stall <= 0;
   end
   else begin
    r_dataout <= i_datain;
    r_dataout_valid <= i_datain_valid;
    r_dataout_stall <= i_dataout_stall;
   end
  end
 end

 assign o_datain_stall = r_dataout_stall;
 assign o_dataout = r_dataout;
 assign o_dataout_valid = r_dataout_valid;

endmodule

