module toe_m_axis_rx_data_rsp_metadata_reg_slice
#(parameter
    N = 8   
) (

    input  wire         clk,
    input  wire         reset,

    input  wire [N-1:0] s_data,
    input  wire         s_valid,
    output wire         s_ready,

    output wire [N-1:0] m_data,
    output wire         m_valid,
    input  wire         m_ready
);
localparam NUM_REG = 3;
    localparam NUM_STAGE = 1;
    localparam REG_STAGE = NUM_STAGE - 1;
    localparam ST_DATA_VLD = 1;
    localparam ST_ZERO = 0;
    localparam ST_ONE = 1;
    localparam ST_TWO = 2;

    (*equivalent_register_removal = "no" *) reg  [NUM_STAGE-1:0] stage_reg;
    (*equivalent_register_removal = "no" *) reg  [NUM_STAGE-1:0] stage_next;
    reg  [N-1:0] data_p1;
    reg  [N-1:0] data_p2;
    reg          load_p1;
    reg          load_p2;
    reg          load_p1_from_p2;
    reg          s_ready_int;
    reg          m_valid_int;
    reg  [1:0]   state;
    reg  [1:0]   state_next;

    assign s_ready = s_ready_int;
    assign m_data = data_p1;
    assign m_valid = m_valid_int;

    always @* begin
        {m_valid_int, s_ready_int, state_next} = {m_valid, s_ready_int, state};
        case (state)
            ST_ZERO : begin
                if (s_valid) begin
                    {m_valid_int, s_ready_int, state_next} = {1'b0, 1'b1, ST_ONE};
                end
            end
            ST_ONE : begin
                if (s_valid) begin
                    {m_valid_int, s_ready_int, state_next} = {1'b0, 1'b0, ST_TWO};
                end
                else if (m_ready) begin
                    {m_valid_int, s_ready_int, state_next} = {1'b1, 1'b1, ST_ZERO};
                end
            end
            ST_TWO : begin
                if (m_ready) begin
                    {m_valid_int, s_ready_int, state_next} = {1'b0, 1'b1, ST_ONE};
                end
            end
            default : begin
                {m_valid_int, s_ready_int, state_next} = {1'b0, 1'b1, ST_ZERO};
            end
        endcase
        load_p1 = 1'b0;
        load_p2 = 1'b0;
        load_p1_from_p2 = 1'b0;
        case (state_next)
            ST_ZERO : begin
                if (s_valid) begin
                    load_p1 = 1'b1;
                end
            end
            ST_ONE : begin
                if (s_valid) begin
                    load_p1 = 1'b1;
                end
                if (m_ready) begin
                    load_p1_from_p2 = 1'b1;
                end
            end
            ST_TWO : begin
                if (m_ready) begin
                    load_p1 = 1'b1;
                end
            end
            default : begin
                if (s_valid) begin
                    load_p1 = 1'b1;
                end
            end
        endcase
        case (state_next)
            ST_ZERO : begin
                if (s_valid) begin
                    load_p2 = 1'b1;
                end
            end
            ST_ONE : begin
                if (s_valid) begin
                    load_p2 = 1'b1;
                end
                if (m_ready) begin
                    load_p2 = 1'b1;
                end
            end
            ST_TWO : begin
                if (m_ready) begin
                    load_p2 = 1'b1;
                end
            end
            default : begin
                if (s_valid) begin
                    load_p2 = 1'b1;
                end
            end
        endcase
    end

    always @(posedge clk) begin
        if (reset) begin
            stage_reg <= {NUM_STAGE{1'b0}};
        end
        else begin
            stage_reg <= stage_next;
        end
    end

    always @(posedge clk) begin
        if (reset) begin
            state <= ST_ZERO;
        end
        else begin
            state <= state_next;
        end
    end

    always @(posedge clk) begin
        if (reset) begin
            s_ready_int <= 1'b0;
        end
        else begin
            s_ready_int <= stage_reg[0];
        end
    end

    always @(posedge clk) begin
        if (reset) begin
            m_valid_int <= 1'b0;
        end
        else begin
            m_valid_int <= stage_reg[1];
        end
    end

    always @(posedge clk) begin
        if (reset) begin
            data_p1 <= {N{1'b0}};
        end
        else if (load_p1) begin
            data_p1 <= s_data;
        end
        else if (load_p1_from_p2) begin
            data_p1 <= data_p2;
        end
    end

    always @(posedge clk) begin
        if (reset) begin
            data_p2 <= {N{1'b0}};
        end
        else if (load_p2) begin
            data_p2 <= s_data;
        end
    end

