module udpAppMux_txLengthNetwork_fifo
#(parameter
    DATA_BITS  = 8,
    DEPTH_BITS = 4
)(
    input  wire                 clk,
    input  wire                 aclr,
    output wire                 empty_n,
    output wire                 full_n,
    input  wire                 read,
    input  wire                 write,
    output wire [DATA_BITS-1:0] dout,
    input  wire [DATA_BITS-1:0] din
);
localparam DEPTH = 1 << DEPTH_BITS;

    reg [DATA_BITS-1:0] mem [DEPTH-1:0];
    reg [DEPTH_BITS-1:0] index;

    assign empty_n = (index != 0);
    assign full_n  = (index != DEPTH-1);
    assign dout    = mem[index];

    always @(posedge clk or posedge aclr) begin
        if (aclr) begin
            index <= 0;
        end else if (write) begin
            if (index < DEPTH-1) begin
                index <= index + 1;
            end
        end
    end

    always @(posedge clk or posedge aclr) begin
        if (aclr) begin
            index <= 0;
        end else if (read) begin
            if (index > 0) begin
                index <= index - 1;
            end
        end
    end

    generate
        genvar i;
        for (i = 0; i < DEPTH; i = i + 1) begin : gen_mem
            always @(posedge clk or posedge aclr) begin
                if (aclr) begin
                    mem[i] <= 0;
                end else if (write && i == index) begin
                    mem[i] <= din;
                end
            end
        end
    endgenerate

endmodule

module Counter_Controller #(
    parameter   DWIDTH = 7
)(
    input                   clk,
    input                   rst_n,
    input                   start_i,
    input   [DWIDTH-1:0]    cnt_val_i,
    input   [DWIDTH-1:0]    cnt_i,
    output                  run_o,
    output                  done_o
);
localparam   S_IDLE = 2'b00,
              S_RUN  = 2'b01,
              S_DONE = 2'b10;

reg    [1:0]    state;
reg    [1:0]    state_n;
reg    [DWIDTH-1:0]    cnt_val;
reg    [DWIDTH-1:0]    cnt_val_n;
reg    run;
reg    done;

always @ (posedge clk or negedge rst_n)
    if (!rst_n)
        state <= S_IDLE;
    else
        state <= state_n;

always @ (state or start_i or cnt_val_i or cnt_i)
    case (state)
        S_IDLE:
            if (start_i)
                state_n <= S_RUN;
            else
                state_n <= S_IDLE;
        S_RUN:
            if (cnt_val == cnt_i)
                state_n <= S_DONE;
            else
                state_n <= S_RUN;
        S_DONE:
            state_n <= S_IDLE;
        default:
            state_n <= S_IDLE;
    endcase

always @ (posedge clk or negedge rst_n)
    if (!rst_n)
        cnt_val <= 0;
    else
        cnt_val <= cnt_val_n;

always @ (state or cnt_val_i)
    case (state)
        S_IDLE:
            cnt_val_n <= 0;
        S_RUN:
            cnt_val_n <= cnt_val_i;
        S_DONE:
            cnt_val_n <= 0;
        default:
            cnt_val_n <= 0;
    endcase

always @ (posedge clk or negedge rst_n)
    if (!rst_n)
        run <= 0;
    else
        run <= run_n;

always @ (state or cnt_val or cnt_i)
    case (state)
        S_IDLE:
            run_n <= 0;
        S_RUN:
            run_n <= 1;
        S_DONE:
            run_n <= 0;
        default:
            run_n <= 0;
    endcase

always @ (posedge clk or negedge rst_n)
    if (!rst_n)
        done <= 0;
    else
        done <= done_n;

always @ (state or cnt_val or cnt_i)
    case (state)
        S_IDLE:
            done_n <= 0;
        S_RUN:
            done_n <= 0;
        S_DONE:
            done_n <= 1;
        default:
            done_n <= 0;
    endcase

assign run_o = run;
assign done_o = done;

endmodule

