module button_pulse 
#(
    parameter MAX_COUNT = 8,    
    parameter DEC_COUNT = 2,    
    parameter MIN_COUNT = 1     
)(
    input wire clk,
    input wire clk_en,
    input wire button,
    input wire reset,
    output wire pulse
);
reg [7:0] comp;
    reg [7:0] count;

    always @(posedge clk) begin
        if (clk_en) begin
            if (reset) begin
                comp <= MAX_COUNT - 1;
                count <= 0;
            end
            else begin
                if (button) begin
                    if (count == 0) begin
                        comp <= MAX_COUNT - 1;
                        count <= 0;
                    end
                    else begin
                        count <= count - 1;
                    end
                end
                else begin
                    if (comp > MIN_COUNT) begin
                        comp <= comp - DEC_COUNT;
                    end
                    else begin
                        comp <= 0;
                    end
                end
            end
        end
    end

    assign pulse = (count == 0) && button;

endmodule

