module fsm_seq_10010_moore(
    input clk,
    input rst_n,
    input x,
    output z
    );
parameter S1 = 3'b000,
            S2 = 3'b001,
            S3 = 3'b010,
            S4 = 3'b011,
            S5 = 3'b100,
            S6 = 3'b101;

    reg [2:0] state;
    reg [2:0] next;

    always @(*) begin
        case (state)
            S1: if (x == 1'b0) next = S2;
                else next = S1;
            S2: if (x == 1'b0) next = S3;
                else next = S1;
            S3: if (x == 1'b0) next = S4;
                else next = S2;
            S4: if (x == 1'b0) next = S5;
                else next = S3;
            S5: if (x == 1'b0) next = S6;
                else next = S4;
            S6: if (x == 1'b0) next = S6;
                else next = S5;
            default: next = S1;
        endcase
    end

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) state <= S1;
        else state <= next;
    end

    assign z = (state == S6) ? 1'b1 : 1'b0;

endmodule

