    parameter FIFO_DEPTH = 256
)
(clk,arstn,data_in,wrreq,rdreq,data_out,usedw,empty,full);

input clk;
input arstn;
input [DATA_WIDTH-1:0]data_in;
input wrreq;
input rdreq;
output [DATA_WIDTH-1:0]data_out;
output reg [clog2_FIFO_DEPTH:0]usedw;
output empty;
output full;
parameter clog2_FIFO_DEPTH = $clog2(FIFO_DEPTH);

reg [DATA_WIDTH-1:0]mem [FIFO_DEPTH-1:0];
reg [clog2_FIFO_DEPTH:0]wrptr;
reg [clog2_FIFO_DEPTH:0]rdptr;
reg wrreq_int;
reg rdreq_int;

always @(posedge clk or negedge arstn)
begin
    if(!arstn)
    begin
        wrptr <= 0;
        rdptr <= 0;
        usedw <= 0;
        empty <= 1;
        full <= 0;
    end
    else
    begin
        wrptr <= wrreq_int ? wrptr + 1 : wrptr;
        rdptr <= rdreq_int ? rdptr + 1 : rdptr;
        usedw <= wrptr - rdptr;
        empty <= (usedw == 0);
        full <= (usedw == FIFO_DEPTH-1);
    end
end

assign wrreq_int = wrreq & ~full;
assign rdreq_int = rdreq & ~empty;
assign data_out = mem[rdptr];

always @(posedge clk or negedge arstn)
begin
    if(!arstn)
    begin
        mem <= 0;
    end
    else
    begin
        if(wrreq_int)
        begin
            mem[wrptr] <= data_in;
        end
    end
end

endmodule

module AND4X4 (IN1,IN2,IN3,IN4,Q);

