module Data_CrossDomain(
    input clkA,
    input FlagIn_clkA, 
    input clkB,
    output FlagOut_clkB,
	input [7:0] dataA,
	output [7:0] dataB
);
reg [2:0] SyncA_clkB;
reg FlagToggle_clkA;
reg clkA_data;
reg clkB_data;
assign FlagOut_clkB = SyncA_clkB[2];
assign dataB = clkB_data;
always @(posedge clkA) begin
    FlagToggle_clkA <= FlagIn_clkA;
    clkA_data <= dataA;
end
always @(posedge clkB) begin
    SyncA_clkB <= {SyncA_clkB[1:0], FlagToggle_clkA};
    clkB_data <= SyncA_clkB[2] ? clkA_data : 8'b0;
end
endmodule

