module testbench;
reg [2:0] A, B;
wire A_greater, A_equal, A_less;
integer i, error = 0;

comparator_3bit comparator_3bit(A, B, A_greater, A_equal, A_less);

initial begin
    for (i = 0; i < 100; i = i + 1) begin
        A = $random;
        B = $random;
        if (A_greater !== (A > B)) begin
            $display("Error: A_greater = %b, A = %b, B = %b", A_greater, A, B);
            error = error + 1;
        end
        if (A_equal !== (A == B)) begin
            $display("Error: A_equal = %b, A = %b, B = %b", A_equal, A, B);
            error = error + 1;
        end
        if (A_less !== (A < B)) begin
            $display("Error: A_less = %b, A = %b, B = %b", A_less, A, B);
            error = error + 1;
        end
    end
    if (error == 0) begin
        $display("Test passed");
    end
    else begin
        $display("Test failed, %d errors", error);
    end
end
endmodule

