module pn_gen_9 (
    input clk,
    input rst,
    input next,
    input [31:0] seed,
    output reg [31:0] num
  );
localparam SEED = 32'h00000000;

  reg [31:0] M_x;
  reg [31:0] M_y;
  reg [31:0] M_z;
  reg [31:0] M_w;
  reg [31:0] M_w_d;

  always @(posedge clk) begin
    if (rst) begin
      M_x <= SEED;
      M_y <= SEED;
      M_z <= SEED;
      M_w <= {32'h00000000, seed};
    end else if (next) begin
      M_x <= M_y;
      M_y <= M_z;
      M_z <= M_w;
      M_w <= M_w_d;
    end
  end

  assign M_w_d = {M_x[30:0], M_x[31] ^ M_y[30:0] ^ M_z[30:0] ^ M_z[31]};

  always @(posedge clk) begin
    num <= M_w;
  end

endmodule

module submuland_2_stage_unsigned_10_bit(
	input  [9:0] a,
	input  [9:0] b,
	input  [9:0] c,
	input  [9:0] d,
	output [9:0] out,
	input clk);
logic  [19:0] stage0;
	logic  [19:0] stage1;

	always @(posedge clk) begin
	stage0 <= ((d - a) * b) & c;
	stage1 <= stage0;
	end

	assign out = stage1;
endmodule

