module gh_delay_programmable_63(
input wire CLK,
input wire rst,
input wire srst,
input wire D,
input wire [5:0] DELAY,
output wire Q
); 

wire Q_d1;
wire Q_d2;
wire Q_d4;
wire Q_d8;
wire Q_d16;
wire Q_d32;
  gh_delay #(
      .DELAY(2))
  U_gh_delay_0(
      .CLK(CLK),
    .rst(rst),
    .srst(srst),
    .D(D),
    .Q(Q_d1));
  gh_delay #(
      .DELAY(4))
  U_gh_delay_1(
      .CLK(CLK),
    .rst(rst),
    .srst(srst),
    .D(D),
    .Q(Q_d2));
  gh_delay #(
      .DELAY(8))
  U_gh_delay_2(
      .CLK(CLK),
    .rst(rst),
    .srst(srst),
    .D(D),
    .Q(Q_d4));
  gh_delay #(
      .DELAY(16))
  U_gh_delay_3(
      .CLK(CLK),
    .rst(rst),
    .srst(srst),
    .D(D),
    .Q(Q_d8));
  gh_delay #(
      .DELAY(32))
  U_gh_delay_4(
      .CLK(CLK),
    .rst(rst),
    .srst(srst),
    .D(D),
    .Q(Q_d16));
  assign Q_d32 = D;
  assign Q = DELAY[0] == 1'b0 ? Q_d1 : DELAY[1] == 1'b0 ? Q_d2 : DELAY[2] == 1'b0 ? Q_d4 : DELAY[3] == 1'b0 ? Q_d8 : DELAY[4] == 1'b0 ? Q_d16 : Q_d32;
  assign Q_d1 = D;
  assign Q_d2 = D;
  assign Q_d4 = D;
  assign Q_d8 = D;
  assign Q_d16 = D;
endmodule

module fsm_trafic_light(clk,reset, red,yellow, green);
input clk, reset;

output red,yellow,green;
reg [1:0] state;


always @(posedge clk or posedge reset)
begin
	if(reset)
		state <= 2'b00;
	else
		case(state)
			2'b00: state <= 2'b01;
			2'b01: state <= 2'b10;
			2'b10: state <= 2'b11;
			2'b11: state <= 2'b00;
		endcase
end


assign red = (state == 2'b00) ? 1'b1 : 1'b0;
assign yellow = (state == 2'b01) ? 1'b1 : 1'b0;
assign green = (state == 2'b11) ? 1'b1 : 1'b0;
endmodule

