module APB_master(input Transfer,              
                  input Wr_Rd,                 
                  input [4:0] Address,         
                  input [31:0] write_data,     
                  output reg [31:0] read_data, 
                  input PCLK,                  
                  input PRESETn,               
                  input PREADY,                
                  input [31:0] PRDATA,         
                  input PSLVERR,               
                  output reg [4:0] PADDR,      
                  output reg PSELx,            
                  output reg PENABLE,          
                  output reg PWRITE,           
                  output reg [31:0] PWDATA);
parameter IDLE = 2'b00, 
          SETUP = 2'b01, 
          ACCESS = 2'b10; 
reg [1:0] state, next_state; 
always @(posedge PCLK or negedge PRESETn) begin 
    if (!PRESETn) begin 
        state <= IDLE; 
    end else begin 
        state <= next_state; 
    end 
end 
always @(state, Transfer, PREADY, PSLVERR) begin 
    case (state) 
        IDLE: begin 
            if (Transfer) begin 
                next_state <= SETUP; 
            end else begin 
                next_state <= IDLE; 
            end 
        end 
        SETUP: begin 
            if (PREADY) begin 
                next_state <= ACCESS; 
            end else begin 
                next_state <= SETUP; 
            end 
        end 
        ACCESS: begin 
            if (PSLVERR) begin 
                next_state <= IDLE; 
            end else if (Transfer) begin 
                next_state <= SETUP; 
            end else begin 
                next_state <= ACCESS; 
            end 
        end 
        default: begin 
            next_state <= IDLE; 
        end 
    endcase 
end 
always @(state, Transfer, PREADY, PSLVERR) begin 
    case (state) 
        IDLE: begin 
            PSELx <= 1'b0; 
            PENABLE <= 1'b0; 
            PWRITE <= 1'b0; 
            PADDR <= 5'b00000; 
            PWDATA <= 32'b00000000000000000000000000000000; 
        end 
        SETUP: begin 
            PSELx <= 1'b1; 
            PENABLE <= 1'b1; 
            PWRITE <= 1'b0; 
            PADDR <= Address; 
            PWDATA <= 32'b00000000000000000000000000000000; 
        end 
        ACCESS: begin 
            PSELx <= 1'b1; 
            PENABLE <= 1'b1; 
            PWRITE <= Wr_Rd; 
            PADDR <= Address; 
            PWDATA <= write_data; 
        end 
        default: begin 
            PSELx <= 1'b0; 
            PENABLE <= 1'b0; 
            PWRITE <= 1'b0; 
            PADDR <= 5'b00000; 
            PWDATA <= 32'b00000000000000000000000000000000; 
        end 
    endcase 
end 
always @(posedge PCLK or negedge PRESETn) begin 
    if (!PRESETn) begin 
        read_data <= 32'b00000000000000000000000000000000; 
    end else begin 
        case (state) 
            ACCESS: begin 
                if (Wr_Rd) begin 
                    read_data <= PRDATA; 
                end else begin 
                    read_data <= 32'b00000000000000000000000000000000; 
                end 
            end 
            default: begin 
                read_data <= 32'b00000000000000000000000000000000; 
            end 
        endcase 
    end 
end 
endmodule

