endmodule

module PulseCounter(
input wire clk,
output wire pulse
); 

parameter [27:0] UpperBound = 28'b00000000000000000000000000000000;
reg [27:0] counter = 28'b00000000000000000000000000000000;
  always @(posedge clk) begin
    if((counter == UpperBound)) begin
      counter <= 28'b00000000000000000000000000000000;
    end
    else begin
      counter <= counter + 1;
    end
  end
  assign pulse = (counter == UpperBound) ? 1'b1 : 1'b0;
endmodule

