module KEY_MUX
(
	input PS2_CLK,
	input PS2_DAT,
	output [9:0]LEDR,
	output [6:0]HEX0,
	output [6:0]HEX1
);
wire [7:0]scan_code;
reg [3:0]S, NS;
reg [7:0]in1, in2, in3, out;
assign LEDR = {S, NS};
assign HEX0 = in3;
assign HEX1 = {S, scan_code};
always @(scan_code)
begin
	case (S)
		4'd0: begin
			NS = 4'd1;
			in1 = scan_code;
		end
		4'd1: begin
			NS = 4'd2;
			in2 = scan_code;
		end
		4'd2: begin
			NS = 4'd3;
			in3 = scan_code;
		end
		4'd3: begin
			NS = 4'd0;
			out = in3;
		end
		default: begin
			NS = 4'd0;
			out = 8'b0;
		end
	endcase
end
keyboard keyboard1
(
	.clk(PS2_CLK),
	.d(PS2_DAT),
	.code(scan_code)
);
display_driver display_driver1
(
	.data(out),
	.hex(HEX0)
);
endmodule

