module file_writer(input_a,input_a_stb,clk,rst,input_a_ack);

  input     clk;
  input     rst;

  input     [63:0] input_a;
  input     input_a_stb;
  output    input_a_ack;
reg [63:0] value;
  reg [1:0] state;
  reg s_input_a_ack;

  initial
    begin
      state = 0;
      s_input_a_ack = 0;
    end

  always @(posedge clk)
    begin
      case (state)
        0: if (input_a_stb)
            begin
              state = 1;
              s_input_a_ack = 1;
              value = input_a;
            end
        1: begin
            $fopena("resp_z");
            $fdisplay("resp_z",value[63:32]);
            $fdisplay("resp_z",value[31:0]);
            $fclose("resp_z");
            state = 0;
            s_input_a_ack = 0;
          end
      endcase
    end

  assign input_a_ack = s_input_a_ack;

  always @(posedge rst)
    begin
      state = 0;
      s_input_a_ack = 0;
    end

endmodule

