module stratixiv_pciehip_pciexp_dcram_rtry (
   wrclock,
   wren,
   wraddress,
   data,
   rdclock,
   rdaddress,
   q
   );

	input   wrclock; 
	input   wren; 
	input   [data_width - 1:0] data; 
	input   [addr_width - 1:0] wraddress; 
	input	rdclock;
	input   [addr_width - 1:0] rdaddress; 
	output  [data_width - 1:0] q;
parameter addr_width = 4;
	parameter data_width = 32;
	reg [data_width - 1:0] ram_block [0:15];
	reg wren_r;
	reg [addr_width - 1:0] wraddr_r;
	reg [data_width - 1:0] wrdata_r;
	reg [addr_width - 1:0] read_addr_r;

	always @(posedge wrclock) begin
		wren_r <= wren;
		wraddr_r <= wraddress;
		wrdata_r <= data;
	end

	always @(posedge wrclock) begin
		if (wren_r) begin
			ram_block[wraddr_r] <= wrdata_r;
		end
	end

	always @(posedge rdclock) begin
		read_addr_r <= rdaddress;
	end

	assign q = ram_block[read_addr_r];
endmodule

