module AdderTreePipelined
#(
    parameter DATA_WIDTH=32,
    parameter LENGTH=8,
    parameter OUT_WIDTH=DATA_WIDTH+$clog2(LENGTH),
    parameter DELAT_STAGES=$clog2(LENGTH)
)
(
    input rst,
    input clk,
    input in_advance,
    input signed [LENGTH*DATA_WIDTH-1:0] in_addends,
    output signed [OUT_WIDTH-1:0] out_sum
);
if (LENGTH==1) begin
        assign out_sum = in_addends;
    end else if (LENGTH==2) begin
        assign out_sum = in_addends;
    end else begin
        wire signed [LENGTH*DATA_WIDTH-1:0] left_addends;
        wire signed [LENGTH*DATA_WIDTH-1:0] right_addends;
        wire signed [OUT_WIDTH-1:0] left_sum;
        wire signed [OUT_WIDTH-1:0] right_sum;
        assign left_addends = in_addends[LENGTH*DATA_WIDTH-1:LENGTH*DATA_WIDTH/2];
        assign right_addends = in_addends[LENGTH*DATA_WIDTH/2-1:0];
        AdderTreePipelined #(
            .DATA_WIDTH(DATA_WIDTH),
            .LENGTH(LENGTH/2),
            .OUT_WIDTH(OUT_WIDTH),
            .DELAT_STAGES(DELAT_STAGES)
        ) left_subtree (
            .rst(rst),
            .clk(clk),
            .in_advance(in_advance),
            .in_addends(left_addends),
            .out_sum(left_sum)
        );
        AdderTreePipelined #(
            .DATA_WIDTH(DATA_WIDTH),
            .LENGTH(LENGTH/2),
            .OUT_WIDTH(OUT_WIDTH),
            .DELAT_STAGES(DELAT_STAGES)
        ) right_subtree (
            .rst(rst),
            .clk(clk),
            .in_advance(in_advance),
            .in_addends(right_addends),
            .out_sum(right_sum)
        );
        assign out_sum = left_sum + right_sum;
    end
endmodule

