        .clk_pix(clk_pix),
        .sim_rst(sim_rst),
        .sdl_sx(sdl_sx),
        .sdl_sy(sdl_sy),
        .sdl_de(sdl_de)
    );
    always_ff @(posedge clk_pix) begin
        sdl_r <= {sdl_r,sdl_r};
        sdl_g <= {sdl_g,sdl_g};
        sdl_b <= {sdl_b,sdl_b};
    end
endmodule

