module adder_sub(s, cout, a, b, cin, cnt, clk, rst);
	input cin, clk, rst;
	input cnt;
	input [n-1:0] a, b;
	output reg cout;
	output reg [n-1:0] s;
parameter n = 32;
	reg [n-1:0] ai, bi, ci;
	always @(posedge clk or negedge rst)
		if (!rst) begin
			s <= 0;
			cout <= 0;
		end
		else begin
			ai <= a;
			bi <= b;
			ci <= cin;
			if (cnt == 0) begin
				s <= ai + bi + ci;
				cout <= 0;
			end
			else begin
				s <= ai - bi - ci;
				cout <= 1;
			end
		end
endmodule

