module FSM_game(
input wire iRST,
input wire iCLK,
input wire [1:0] iA,
input wire [1:0] iB,
output wire oA,
output wire oB
); 

parameter [1:0]
  DRAW = 0,
  B_LEAD = 1,
  B_WIN = 2,
  A_LEAD = 3,
  A_WIN = 4;
reg [1:0] sSTATE;
reg [1:0] sNEXT_STATE;
reg [1:0] sWIN;
  always @(posedge iCLK, posedge iRST) begin
    if((iRST == 1'b1)) begin
      sSTATE <= DRAW;
    end else begin
      sSTATE <= sNEXT_STATE;
    end
  end
  always @(sSTATE, iA, iB) begin
    case(sSTATE)
    DRAW : begin
      if((iA == 2'b00 && iB == 2'b00)) begin
        sNEXT_STATE <= DRAW;
      end
      else if((iA == 2'b01 && iB == 2'b00)) begin
        sNEXT_STATE <= B_LEAD;
      end
      else if((iA == 2'b00 && iB == 2'b01)) begin
        sNEXT_STATE <= A_LEAD;
      end
      else if((iA == 2'b10 && iB == 2'b00)) begin
        sNEXT_STATE <= B_WIN;
      end
      else if((iA == 2'b00 && iB == 2'b10)) begin
        sNEXT_STATE <= A_WIN;
      end
      else begin
        sNEXT_STATE <= DRAW;
      end
    end
    B_LEAD : begin
      if((iA == 2'b00 && iB == 2'b00)) begin
        sNEXT_STATE <= DRAW;
      end
      else if((iA == 2'b01 && iB == 2'b00)) begin
        sNEXT_STATE <= B_LEAD;
      end
      else if((iA == 2'b00 && iB == 2'b01)) begin
        sNEXT_STATE <= A_LEAD;
      end
      else if((iA == 2'b10 && iB == 2'b00)) begin
        sNEXT_STATE <= B_WIN;
      end
      else if((iA == 2'b00 && iB == 2'b10)) begin
        sNEXT_STATE <= A_WIN;
      end
      else begin
        sNEXT_STATE <= DRAW;
      end
    end
    B_WIN : begin
      sNEXT_STATE <= B_WIN;
    end
    A_LEAD : begin
      if((iA == 2'b00 && iB == 2'b00)) begin
        sNEXT_STATE <= DRAW;
      end
      else if((iA == 2'b01 && iB == 2'b00)) begin
        sNEXT_STATE <= B_LEAD;
      end
      else if((iA == 2'b00 && iB == 2'b01)) begin
        sNEXT_STATE <= A_LEAD;
      end
      else if((iA == 2'b10 && iB == 2'b00)) begin
        sNEXT_STATE <= B_WIN;
      end
      else if((iA == 2'b00 && iB == 2'b10)) begin
        sNEXT_STATE <= A_WIN;
      end
      else begin
        sNEXT_STATE <= DRAW;
      end
    end
    A_WIN : begin
      sNEXT_STATE <= A_WIN;
    end
    default : begin
      sNEXT_STATE <= DRAW;
    end
    endcase
  end
  always @(sSTATE) begin
    case(sSTATE)
    DRAW : begin
      sWIN <= 2'b00;
    end
    B_LEAD : begin
      sWIN <= 2'b00;
    end
    B_WIN : begin
      sWIN <= 2'b01;
    end
    A_LEAD : begin
      sWIN <= 2'b00;
    end
    A_WIN : begin
      sWIN <= 2'b10;
    end
    default : begin
      sWIN <= 2'b00;
    end
    endcase
  end
  assign oA = sWIN[1];
  assign oB = sWIN[0];
endmodule

