module isqrt
(
    input      [31:0] x,
    output reg [15:0] y
);
reg [31:0] x0;
reg [31:0] x1;
reg [15:0] y0;

always @* begin
    x0 = x;
    x1 = x;
    y0 = 0;
    for (int i = 0; i < 32; i = i + 1) begin
        y0 = y0 << 1;
        if (x1 >= 2**i) begin
            x1 = x1 - 2**i;
            y0 = y0 + 1;
        end
    end
    y = y0[15:0];
end

endmodule

