module serial(clk, reset, rxD,sout,signal,counter);
input clk;      
input reset;    
input rxD;   

output reg [n-1:0]sout; 
output reg signal;   
output reg [31:0]counter;
parameter n = 30;   
parameter count = 4; 
reg [1:0]delay;      
reg [31:0]counter;   
reg [7:0]s_in;      
top top1(clk,reset,rxD,s_in);
always@(posedge clk)
begin
    if(reset)
    begin
        counter <= 0;
        sout <= 0;
        signal <= 0;
    end
    else
    begin
        if(counter == count)
        begin
            counter <= 0;
            sout <= {s_in,sout[n-1:8]};
            signal <= 1;
        end
        else
        begin
            counter <= counter + 1;
            sout <= sout;
            signal <= 0;
        end
    end
end
endmodule

