module twocmp(input [31:0]A,output [31:0]B);
genvar i;
generate
for(i=0;i<32;i=i+1)
begin
if(i==0)
B[i]=A[i];
else
begin
if(|A[0:i-1])
B[i]=~A[i];
else
B[i]=A[i];
end
end
endgenerate
endmodule

module arbiter (
clock, 
reset, 
req_0,
req_1, 
gnt_0,
gnt_1
);

input clock, reset, req_0, req_1;
output gnt_0, gnt_1;
reg gnt_0, gnt_1;

always @(posedge clock or posedge reset)
begin
	if (reset)
	begin
		gnt_0 <= 0;
		gnt_1 <= 0;
	end
	else
	begin
		if (req_0 && req_1)
		begin
			gnt_0 <= 1;
			gnt_1 <= 0;
		end
		else if (req_0)
		begin
			gnt_0 <= 1;
			gnt_1 <= 0;
		end
		else if (req_1)
		begin
			gnt_0 <= 0;
			gnt_1 <= 1;
		end
		else
		begin
			gnt_0 <= 0;
			gnt_1 <= 0;
		end
	end
end

endmodule

module NAND3C(Y,A,B,C);
 input A,B,C;
 output Y;
wire A__bar,B__bar;

 not (A__bar, A);
 not (B__bar, B);
 and (Y, A__bar, B__bar, C);

 specify

 specparam
 in1_lh_qn_hl=10,
 in2_lh_qn_hl=10,
 in3_lh_qn_hl=10;

 (A *> Y) = (in1_lh_qn_hl,in1_lh_qn_hl);
 (B *> Y) = (in2_lh_qn_hl,in2_lh_qn_hl);
 (C *> Y) = (in3_lh_qn_hl,in3_lh_qn_hl);
 endspecify

endmodule

