module Bin2BCDConverter_4
#(
	parameter INPUT_BIT_WIDTH  = 8
)
(
    input [(INPUT_BIT_WIDTH-1):0] Input,
    output reg [3:0] Digit3,
    output reg [3:0] Digit2,
    output reg [3:0] Digit1,
    output reg [3:0] Digit0
);
always @(*) begin
        for (int i = 0; i < INPUT_BIT_WIDTH; i = i + 1) begin
            if (Digit3 >= 5) Digit3 = Digit3 + 3;
            if (Digit2 >= 5) Digit2 = Digit2 + 3;
            if (Digit1 >= 5) Digit1 = Digit1 + 3;
            if (Digit0 >= 5) Digit0 = Digit0 + 3;
            Digit3 = {Digit3[2:0], Digit3[3]};
            Digit2 = {Digit2[2:0], Digit2[3]};
            Digit1 = {Digit1[2:0], Digit1[3]};
            Digit0 = {Digit0[2:0], Digit0[3]};
            if (i == 0) Digit0[0] = Input[0];
            else if (i == 1) Digit0[0] = Input[1];
            else if (i == 2) Digit0[0] = Input[2];
            else if (i == 3) Digit0[0] = Input[3];
            else if (i == 4) Digit0[0] = Input[4];
            else if (i == 5) Digit0[0] = Input[5];
            else if (i == 6) Digit0[0] = Input[6];
            else if (i == 7) Digit0[0] = Input[7];
        end
    end
endmodule

