module NBitCounterChain #(
   parameter counterSize   = 16,
   parameter numOfCounters = 3054
) (
   input  wire                   clk,
   input  wire                   reset,
   output wire [counterSize-1:0] outCount
);
reg [counterSize-1:0] counts [0:numOfCounters-1];
   reg                   terminalCounts [0:numOfCounters-1];
   wire                  enable [0:numOfCounters-1];
   assign enable[0] = 1'b1;
   generate
      genvar i;
      for (i = 0; i < numOfCounters; i = i + 1) begin : counter
         NBitCounter #(
            .counterSize(counterSize)
         ) counterInst (
            .clk(clk),
            .reset(reset),
            .enable(enable[i]),
            .count(counts[i]),
            .terminalCount(terminalCounts[i])
         );
         if (i > 0) begin
            assign enable[i] = terminalCounts[i-1];
         end
      end
   endgenerate
   assign outCount = counts[numOfCounters-1];
endmodule

