module vga_sync(
input wire clk,
input wire rst,
output reg active,
output reg hsync,
output reg vsync,
output wire [9:0] xaddr,
output wire [9:0] yaddr
); 

parameter [9:0] H_ACTIVE = 640;
parameter [9:0] H_FRONT_PORCH = 16;
parameter [9:0] H_BACK_PORCH = 48;
parameter [9:0] H_RETRACE = 96;
parameter [9:0] V_ACTIVE = 480;
parameter [9:0] V_FRONT_PORCH = 10;
parameter [9:0] V_BACK_PORCH = 33;
parameter [9:0] V_RETRACE = 2;
reg [9:0] h_count_reg;
reg [9:0] v_count_reg;
  always @(posedge clk, posedge rst) begin
    if((rst == 1'b1)) begin
      h_count_reg <= 0;
      v_count_reg <= 0;
    end else begin
      if((h_count_reg < (H_ACTIVE + H_FRONT_PORCH + H_BACK_PORCH + H_RETRACE))) begin
        h_count_reg <= h_count_reg + 1;
      end
      else begin
        h_count_reg <= 0;
        if((v_count_reg < (V_ACTIVE + V_FRONT_PORCH + V_BACK_PORCH + V_RETRACE))) begin
          v_count_reg <= v_count_reg + 1;
        end
        else begin
          v_count_reg <= 0;
        end
      end
    end
  end
  assign xaddr = h_count_reg;
  assign yaddr = v_count_reg;
  always @(posedge clk, posedge rst) begin
    if((rst == 1'b1)) begin
      active <= 1'b0;
      hsync <= 1'b0;
      vsync <= 1'b0;
    end else begin
      if((h_count_reg < (H_ACTIVE + H_FRONT_PORCH + H_BACK_PORCH + H_RETRACE))) begin
        if((h_count_reg < (H_ACTIVE + H_FRONT_PORCH + H_BACK_PORCH))) begin
          hsync <= 1'b1;
        end
        else begin
          hsync <= 1'b0;
        end
      end
      else begin
        hsync <= 1'b0;
      end
      if((v_count_reg < (V_ACTIVE + V_FRONT_PORCH + V_BACK_PORCH + V_RETRACE))) begin
        if((v_count_reg < (V_ACTIVE + V_FRONT_PORCH + V_BACK_PORCH))) begin
          vsync <= 1'b1;
        end
        else begin
          vsync <= 1'b0;
        end
      end
      else begin
        vsync <= 1'b0;
      end
      if((h_count_reg < (H_ACTIVE + H_FRONT_PORCH + H_BACK_PORCH + H_RETRACE)) && (v_count_reg < (V_ACTIVE + V_FRONT_PORCH + V_BACK_PORCH + V_RETRACE))) begin
        active <= 1'b1;
      end
      else begin
        active <= 1'b0;
      end
    end
  end
endmodule

