module TopModule(
    input  clk,
    input  reset,
    input  data,
    output reg start_shifting
    );
localparam [1:0] IDLE = 2'b00;
    localparam [1:0] SEARCH = 2'b01;
    localparam [1:0] FOUND = 2'b10;
    localparam [1:0] DONE = 2'b11;
    reg [1:0] state;
    reg [1:0] next_state;
    reg [3:0] count;
    reg [3:0] next_count;
    reg [3:0] shift_reg;
    reg [3:0] next_shift_reg;
    always @(posedge clk) begin
        if (reset) begin
            state <= IDLE;
            count <= 4'b0000;
            shift_reg <= 4'b0000;
        end
        else begin
            state <= next_state;
            count <= next_count;
            shift_reg <= next_shift_reg;
        end
    end
    always @(state, count, shift_reg, data) begin
        next_state <= state;
        next_count <= count;
        next_shift_reg <= shift_reg;
        case (state)
            IDLE: begin
                if (data) begin
                    next_state <= SEARCH;
                    next_count <= 4'b0000;
                    next_shift_reg <= 4'b0000;
                end
            end
            SEARCH: begin
                if (count == 4) begin
                    next_state <= DONE;
                end
                else begin
                    next_state <= SEARCH;
                    next_count <= count + 1;
                    next_shift_reg <= {shift_reg[2:0], data};
                end
            end
            FOUND: begin
                next_state <= FOUND;
                next_count <= count;
                next_shift_reg <= shift_reg;
            end
            DONE: begin
                if (data) begin
                    next_state <= FOUND;
                    next_count <= 4'b0000;
                    next_shift_reg <= 4'b0000;
                end
                else begin
                    next_state <= DONE;
                    next_count <= count;
                    next_shift_reg <= shift_reg;
                end
            end
        endcase
        if (state == FOUND) begin
            start_shifting <= 1;
        end
        else begin
            start_shifting <= 0;
        end
    end
endmodule

