module TopModule(
    input  clk,
    input  aresetn,
    input  x,
    output z
    );
reg [1:0] state;
    reg [1:0] next_state;
    reg z_reg;
    reg z_next;
    always @(posedge clk or negedge aresetn) begin
        if (!aresetn) begin
            state <= 2'b00;
            z_reg <= 1'b0;
        end
        else begin
            state <= next_state;
            z_reg <= z_next;
        end
    end
    always @(state, x) begin
        case (state)
            2'b00: begin
                if (x == 1'b1) begin
                    next_state <= 2'b01;
                    z_next <= 1'b0;
                end
                else begin
                    next_state <= 2'b00;
                    z_next <= 1'b0;
                end
            end
            2'b01: begin
                if (x == 1'b0) begin
                    next_state <= 2'b10;
                    z_next <= 1'b0;
                end
                else begin
                    next_state <= 2'b01;
                    z_next <= 1'b0;
                end
            end
            2'b10: begin
                if (x == 1'b1) begin
                    next_state <= 2'b11;
                    z_next <= 1'b0;
                end
                else begin
                    next_state <= 2'b00;
                    z_next <= 1'b0;
                end
            end
            2'b11: begin
                if (x == 1'b0) begin
                    next_state <= 2'b10;
                    z_next <= 1'b1;
                end
                else begin
                    next_state <= 2'b01;
                    z_next <= 1'b0;
                end
            end
        endcase
    end
    assign z = z_reg;
endmodule

