reg [1:0] state;
always @(posedge clk or posedge reset)
begin
	if (reset)
		state <= 2'b00;
	else
		case (state)
			2'b00: if (s == 0) state <= 2'b00; else state <= 2'b01;
			2'b01: if (w == 1) state <= 2'b10; else state <= 2'b01;
			2'b10: if (w == 1) state <= 2'b11; else state <= 2'b01;
			2'b11: if (w == 1) state <= 2'b11; else state <= 2'b01;
		endcase
end
always @(posedge clk or posedge reset)
begin
	if (reset)
		z <= 1'b0;
	else
		case (state)
			2'b00: z <= 1'b0;
			2'b01: z <= 1'b0;
			2'b10: z <= 1'b0;
			2'b11: z <= 1'b1;
