module TopModule(
    input  clk,
    input  reset,
    input  data,
    input  done_counting,
    input  ack,
    output shift_ena,
    output counting,
    output done
    );
parameter [1:0] 
        IDLE = 2'b00,
        WAIT = 2'b01,
        COUNT = 2'b10,
        DONE = 2'b11;

    reg [1:0] state;
    reg [1:0] next_state;
    reg shift_ena_reg;
    reg counting_reg;
    reg done_reg;

    always @(posedge clk or posedge reset) begin
        if (reset) begin
            state <= IDLE;
        end else begin
            state <= next_state;
        end
    end

    always @(state, data) begin
        case (state)
            IDLE: begin
                if (data == 4'b1101) begin
                    next_state <= WAIT;
                end else begin
                    next_state <= IDLE;
                end
            end
            WAIT: begin
                if (data == 4'b1101) begin
                    next_state <= WAIT;
                end else begin
                    next_state <= COUNT;
                end
            end
            COUNT: begin
                if (done_counting) begin
                    next_state <= DONE;
                end else begin
                    next_state <= COUNT;
                end
            end
            DONE: begin
                if (ack) begin
                    next_state <= IDLE;
                end else begin
                    next_state <= DONE;
                end
            end
            default: begin
                next_state <= IDLE;
            end
        endcase
    end

    always @(state) begin
        case (state)
            IDLE: begin
                shift_ena_reg <= 1'b0;
                counting_reg <= 1'b0;
                done_reg <= 1'b0;
            end
            WAIT: begin
                shift_ena_reg <= 1'b0;
                counting_reg <= 1'b0;
                done_reg <= 1'b0;
            end
            COUNT: begin
                shift_ena_reg <= 1'b0;
                counting_reg <= 1'b1;
                done_reg <= 1'b0;
            end
            DONE: begin
                shift_ena_reg <= 1'b0;
                counting_reg <= 1'b0;
                done_reg <= 1'b1;
            end
            default: begin
                shift_ena_reg <= 1'b0;
                counting_reg <= 1'b0;
                done_reg <= 1'b0;
            end
        endcase
    end

    always @(posedge clk or posedge reset) begin
        if (reset) begin
            shift_ena <= 1'b0;
        end else begin
            shift_ena <= shift_ena_reg;
        end
    end

    always @(posedge clk or posedge reset) begin
        if (reset) begin
            counting <= 1'b0;
        end else begin
            counting <= counting_reg;
        end
    end

    always @(posedge clk or posedge reset) begin
        if (reset) begin
            done <= 1'b0;
        end else begin
            done <= done_reg;
        end
    end

endmodule

