module TopModule (
  input clk,
  input areset,
  input train_valid,
  input train_taken,
  output logic [1:0] state
);
logic [1:0] state_next;

  always_ff @(posedge clk, posedge areset) begin
    if (areset) begin
      state <= 2'b01;
    end else begin
      if (train_valid && train_taken) begin
        state <= state_next;
      end else begin
        state <= state_next;
      end
    end
  end

  always_comb begin
    if (train_valid && train_taken) begin
      state_next = state + 2'b01;
    end else if (train_valid && !train_taken) begin
      state_next = state - 2'b01;
    end else begin
      state_next = state;
    end
  end

endmodule

