module TopModule (
  input clk,
  input reset,
  input data,
  output reg shift_ena,
  output reg counting,
  input done_counting,
  output reg done,
  input ack
);
parameter [1:0] IDLE = 2'b00,
                START = 2'b01,
                COUNTING = 2'b10,
                DONE = 2'b11;

  reg [1:0] state;
  reg [1:0] next_state;

  always @(posedge clk or posedge reset) begin
    if (reset) begin
      state <= IDLE;
    end else begin
      state <= next_state;
    end
  end

  always @(state or data or done_counting or ack) begin
    case (state)
      IDLE: begin
        next_state = (data == 1'b1) ? START : IDLE;
      end
      START: begin
        next_state = (data == 1'b0) ? START : COUNTING;
      end
      COUNTING: begin
        next_state = (done_counting) ? DONE : COUNTING;
      end
      DONE: begin
        next_state = (ack) ? IDLE : DONE;
      end
      default: begin
        next_state = IDLE;
      end
    endcase
  end

  always @(state or data) begin
    case (state)
      IDLE: begin
        shift_ena = 1'b0;
        counting = 1'b0;
        done = 1'b0;
      end
      START: begin
        shift_ena = 1'b0;
        counting = 1'b0;
        done = 1'b0;
      end
      COUNTING: begin
        shift_ena = 1'b0;
        counting = 1'b1;
        done = 1'b0;
      end
      DONE: begin
        shift_ena = 1'b0;
        counting = 1'b0;
        done = 1'b1;
      end
      default: begin
        shift_ena = 1'b0;
        counting = 1'b0;
        done = 1'b0;
      end
    endcase
  end

endmodule

